  <div class="toast" id="toast" role="status"><span class="toast-icon"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4 10-10"/></svg></span><span><strong id="toastTitle">Gata</strong><span id="toastText">Acțiunea a fost finalizată.</span></span></div>

  <script>
    (()=>{
      'use strict';
      const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
      const body=document.body, menu=$('#mobileMenu'), toast=$('#toast');
      const openMenu=()=>{menu?.classList.add('open');menu?.setAttribute('aria-hidden','false');body.style.overflow='hidden'};
      const closeMenu=()=>{menu?.classList.remove('open');menu?.setAttribute('aria-hidden','true');body.style.overflow=''};
      $('#menuOpen')?.addEventListener('click',openMenu);$('#menuClose')?.addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
      const showToast=(title,text)=>{if(!toast)return;$('#toastTitle').textContent=title;$('#toastText').textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2800)};
      $$('[data-invoice]').forEach(btn=>btn.addEventListener('click',()=>showToast('Factură pregătită',`${btn.dataset.invoice}.pdf a fost generată.`)));
      $$('[data-review]').forEach(btn=>btn.addEventListener('click',()=>showToast('Recenzie','Formularul de feedback a fost deschis.')));
      $$('[data-support]').forEach(btn=>btn.addEventListener('click',()=>showToast('Suport','Solicitarea poate fi trimisă din centrul de ajutor.')));
      $('#downloadInvoices')?.addEventListener('click',()=>showToast('Arhivă pregătită','Toate facturile au fost incluse într-un fișier ZIP.'));
      $('#notificationButton')?.addEventListener('click',()=>showToast('Notificări','Nu ai actualizări noi despre comenzi.'));

      let activeFilter='all', newestFirst=true;
      const orders=$$('.order-card'), stack=$('#ordersStack'), empty=$('#emptyState'), search=$('#orderSearch');
      const applyFilters=()=>{const q=(search?.value||'').trim().toLowerCase();let visible=0;orders.forEach(order=>{const category=order.dataset.category;const matchesFilter=activeFilter==='all'||category===activeFilter;const matchesSearch=!q||(order.dataset.search||'').includes(q);const show=matchesFilter&&matchesSearch;order.hidden=!show;if(show)visible++});empty?.classList.toggle('visible',visible===0)};
      $$('.tab').forEach(tab=>tab.addEventListener('click',()=>{$$('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');activeFilter=tab.dataset.filter;applyFilters()}));
      search?.addEventListener('input',applyFilters);
      $('#sortButton')?.addEventListener('click',()=>{newestFirst=!newestFirst;const sorted=[...orders].sort((a,b)=>newestFirst?Number(b.dataset.date)-Number(a.dataset.date):Number(a.dataset.date)-Number(b.dataset.date));sorted.forEach(order=>stack?.appendChild(order));showToast('Ordine schimbată',newestFirst?'Cele mai noi apar primele.':'Cele mai vechi apar primele.')});
      if(!matchMedia('(prefers-reduced-motion: reduce)').matches){
        $$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:620,delay:70+i*75,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));
        const route=$('#heroRoute');if(route){const length=route.getTotalLength();route.style.strokeDasharray=length;route.style.strokeDashoffset=length;route.animate([{strokeDashoffset:length},{strokeDashoffset:0}],{duration:1700,delay:250,easing:'cubic-bezier(.22,.8,.2,1)',fill:'forwards'})}
        const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});observer.unobserve(entry.target)}}),{threshold:.08});$$('.order-card,.insight-card').forEach(el=>observer.observe(el));
      }
      applyFilters();
    })();
  </script>
  <script>
  (function(){
    function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
    var a = nvAuth();
    if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
    var AH = { 'Authorization':'Bearer '+a.token };
    function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
    function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
    function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }
    function money(v,c){ if(v==null||v==='') return ''; c=(c||'lei'); if(String(c).toLowerCase()==='ron')c='lei'; return new Intl.NumberFormat('ro-RO').format(Math.round(Number(v)))+' '+c; }
    function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
    function fmtDate(iso){ if(!iso)return ''; var d=new Date(iso); if(isNaN(d))return ''; return d.toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'}); }
    function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; var em=box.querySelector('strong + span'); if(em&&u.email)em.textContent=u.email; } }
    document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
    hydrateUser(a.user);
    api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

    api('acc-orders').then(function(d){ if(!(d&&d.success))return; var list=Array.isArray(d.data)?d.data:[];
      if(d.stats){ var hs=document.querySelector('.hero-summary strong'); if(hs)hs.textContent=(d.stats.total_orders||list.length)+' comenzi · '+money(d.stats.total_spent,'lei'); }
      var stack=document.querySelector('#ordersStack'); if(!stack||!list.length)return;
      function cat(o){ if(o.status==='refunded')return 'refunded'; if(o.status==='completed')return 'completed'; if(o.is_paid)return 'paid'; return 'pending'; }
      function label(o){ var s=o.status; return s==='refunded'?'Rambursată':s==='completed'?'Finalizată':o.is_paid?'Plătită':s==='pending'?'În așteptare':(s||''); }
      function dnum(o){ if(!o.created_at)return '0'; return String(o.created_at).slice(0,10).replace(/-/g,''); }
      stack.innerHTML=list.map(function(o){ var c=cat(o); var ev=o.event||('Comanda '+o.order_number); var search=((o.order_number||'')+' '+(o.event||'')).toLowerCase();
        return '<article class="order-card" data-category="'+c+'" data-date="'+dnum(o)+'" data-search="'+esc(search)+'">'
         +'<header class="order-head"><div class="order-code"><span class="order-icon"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 4h14v16H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></svg></span><span><small>Comandă din '+esc(fmtDate(o.created_at))+'</small><h2>#'+esc(o.order_number)+'</h2></span></div><div class="order-meta"><span class="status '+c+'">'+esc(label(o))+'</span><span class="order-total"><strong>'+esc(money(o.total,o.currency))+'</strong><span>'+esc(o.payment_method||'Card')+'</span></span></div></header>'
         +'<div class="order-body"><div class="order-items"><div class="item-row"><span class="item-thumb" style="background:var(--pine-800)"></span><span class="item-copy"><strong>'+esc(ev)+'</strong><span>'+(o.event_date?esc(fmtDate(o.event_date))+' · ':'')+(o.tickets_count||0)+' bilete</span></span><span class="item-price">'+esc(money(o.total,o.currency))+'<span>'+(o.tickets_count||0)+' bilete</span></span></div></div><aside class="order-side"><div class="order-actions"><a class="btn btn-primary wide" href="/cont/comanda?id='+o.id+'">Vezi comanda</a><a class="btn btn-ghost" href="/cont/bilete">Bilete</a></div></aside></div>'
         +'</article>'; }).join('');
      var cards=[].slice.call(stack.querySelectorAll('.order-card'));
      var searchEl=document.querySelector('#orderSearch'); var empty=document.querySelector('#emptyState'); var af='all';
      function apply(){ var q=((searchEl&&searchEl.value)||'').trim().toLowerCase(); var vis=0; cards.forEach(function(card){ var mc=af==='all'||card.dataset.category===af; var ms=!q||(card.dataset.search||'').indexOf(q)>=0; var show=mc&&ms; card.hidden=!show; if(show)vis++; }); if(empty)empty.classList.toggle('visible',vis===0); }
      document.querySelectorAll('.tab').forEach(function(t){ var cl=t.cloneNode(true); t.parentNode.replaceChild(cl,t); cl.addEventListener('click',function(){ document.querySelectorAll('.tab').forEach(function(x){x.classList.remove('active');}); cl.classList.add('active'); af=cl.dataset.filter; apply(); }); });
      if(searchEl){ var c2=searchEl.cloneNode(true); searchEl.parentNode.replaceChild(c2,searchEl); searchEl=c2; searchEl.addEventListener('input',apply); }
      var sb=document.querySelector('#sortButton'); if(sb){ var sc=sb.cloneNode(true); sb.parentNode.replaceChild(sc,sb); var desc=true; sc.addEventListener('click',function(){ desc=!desc; cards.sort(function(x,y){ var dx=Number(x.dataset.date||0), dy=Number(y.dataset.date||0); return desc?dy-dx:dx-dy; }); cards.forEach(function(card){ stack.appendChild(card); }); }); }
      apply();
    });
  })();
  </script>
